import importlib.util
import os
import shlex
import subprocess
import sys
from pathlib import Path

from fakes import fake_command, recorded_args

BUILD_DRIVE = Path(__file__).resolve().parent / "build-drive.sh"

EXPORTED = """\
# This file was autogenerated by uv via the following command:
#    uv export --frozen --no-dev --no-hashes --no-emit-project
pyside6-essentials==6.4.2
    # via mediatagger
python-mpv==0.9.1
    # via mediatagger
shiboken6==6.4.2
    # via pyside6-essentials
"""


def fake_build_env(tmp_path, record):
    """Fake uv, apt-ftparchive and python3.13 on PATH, a Pi-like apt root with one .deb, home under tmp_path."""
    bin_dir = tmp_path / "bin"
    bin_dir.mkdir()
    (tmp_path / "exported.txt").write_text(EXPORTED)
    record.mkdir()
    fake_command(bin_dir, "uv", f"""
if [ "$1" = export ]; then
  shift
  for a; do
    case "$a" in --frozen|--no-dev|--no-hashes|--no-emit-project) ;; *) exit 2;; esac
  done
  [ $# -eq 4 ] || exit 2
  cat "{tmp_path / 'exported.txt'}"
  exit 0
fi
i=1; while [ -e "{record}/$i" ]; do i=$((i+1)); done
mkdir "{record}/$i"
printf '%s\\0' "$@" > "{record}/$i/args"
prev=
for a; do
  case "$prev" in -r|--requirement|--requirements) cp "$a" "{record}/$i/requirements";; esac
  case "$a" in --requirement=*|--requirements=*) cp "${{a#*=}}" "{record}/$i/requirements";; esac
  prev=$a
done""")
    fake_command(bin_dir, "apt-ftparchive", "printf 'Package: libmpv2\\n'")
    fake_command(bin_dir, "python3.13", f'exec "{sys.executable}" "$@"')
    aptpi = tmp_path / "aptpi"
    archives = aptpi / "var" / "cache" / "apt" / "archives"
    archives.mkdir(parents=True)
    (archives / "libmpv2_0.39.0-3_arm64.deb").write_bytes(b"!<arch>\ndeb")
    (tmp_path / "home").mkdir()
    return {
        **os.environ,
        "PATH": f"{bin_dir}{os.pathsep}{os.environ['PATH']}",
        "HOME": str(tmp_path / "home"),
        "APTPI": str(aptpi),
    }


def uv_pip_install_calls(record):
    calls = []
    for call in sorted(record.iterdir(), key=lambda d: int(d.name)):
        args = [a.decode() for a in recorded_args(call / "args")]
        if args[:2] != ["pip", "install"]:
            continue
        requirements = call / "requirements"
        calls.append({
            "args": args[2:],
            "requirements": requirements.read_text() if requirements.exists() else "",
        })
    return calls


def requirement_specs(text):
    return {
        line.split(";")[0].strip()
        for line in text.splitlines()
        if line.strip() and not line.strip().startswith("#")
    }


def option_value(args, name):
    return next((args[i + 1] for i, a in enumerate(args[:-1]) if a == name), None)


def positional_specs(args):
    takes_value = {"--python", "--target", "-r", "--requirement", "--requirements"}
    specs, skip = set(), False
    for a in args:
        if skip:
            skip = False
        elif a in takes_value:
            skip = True
        elif not a.startswith("-"):
            specs.add(a)
    return specs


def test_build_drive_installs_exactly_the_uv_exported_locked_packages_into_the_drive_lib_for_the_pis_python(tmp_path):
    record = tmp_path / "uv-calls"
    env = fake_build_env(tmp_path, record)
    drive = tmp_path / "drive"
    drive.mkdir()

    subprocess.run(["sh", str(BUILD_DRIVE), str(drive)], env=env)

    lib = drive / "mediatagger" / "lib-linux-aarch64-cp313"
    installs = [
        {
            "python": option_value(call["args"], "--python"),
            "target": option_value(call["args"], "--target"),
            "specs": positional_specs(call["args"]) | requirement_specs(call["requirements"]),
        }
        for call in uv_pip_install_calls(record)
    ]
    assert installs == [{
        "python": "/usr/bin/python3.13",
        "target": str(lib),
        "specs": requirement_specs(EXPORTED),
    }]


INSTALLED_PACKAGES = {
    "mpv.py": "import os\n",
    "PySide6/__init__.py": "",
    "PySide6/scripts/__init__.py": "",
    "PySide6/scripts/deploy_lib/__init__.py": "",
    "PySide6/scripts/deploy_lib/config.py": "x = 1\n",
}


def fake_uv_installing_packages(tmp_path, files):
    """Replace the fake uv with one whose `pip install --target <lib>` writes `files` into <lib>."""
    writes = "\n".join(
        f'mkdir -p "$target/{os.path.dirname(name)}" && printf %s {shlex.quote(body)} > "$target/{name}"'
        for name, body in files.items()
    )
    fake_command(tmp_path / "bin", "uv", f"""
if [ "$1" = export ]; then cat "{tmp_path / 'exported.txt'}"; exit 0; fi
target=; prev=
for a; do [ "$prev" = --target ] && target=$a; prev=$a; done
{writes}""")


def test_build_drive_leaves_unchecked_hash_bytecode_next_to_every_installed_module_except_under_deploy_lib(tmp_path):
    env = fake_build_env(tmp_path, tmp_path / "uv-calls")
    fake_uv_installing_packages(tmp_path, INSTALLED_PACKAGES)
    drive = tmp_path / "drive"
    drive.mkdir()

    subprocess.run(["sh", str(BUILD_DRIVE), str(drive)], env=env)

    lib = drive / "mediatagger" / "lib-linux-aarch64-cp313"
    unchecked_hash = 0b01
    flags = {
        str(module.relative_to(lib)): int.from_bytes(pyc.read_bytes()[4:8], "little") if pyc.exists() else None
        for module in lib.rglob("*.py")
        for pyc in [Path(importlib.util.cache_from_source(str(module)))]
    }
    assert flags == {
        name: None if "deploy_lib" in Path(name).parts else unchecked_hash
        for name in INSTALLED_PACKAGES
    }


def test_build_drive_removes_a_package_left_in_the_drive_lib_by_an_earlier_build(tmp_path):
    env = fake_build_env(tmp_path, tmp_path / "uv-calls")
    fake_uv_installing_packages(tmp_path, INSTALLED_PACKAGES)
    drive = tmp_path / "drive"
    lib = drive / "mediatagger" / "lib-linux-aarch64-cp313"
    stale = lib / "oldpkg"
    stale.mkdir(parents=True)
    (stale / "__init__.py").write_text("")

    subprocess.run(["sh", str(BUILD_DRIVE), str(drive)], env=env)

    assert {str(p.relative_to(lib)) for p in lib.rglob("*.py")} == set(INSTALLED_PACKAGES)


def test_build_drive_copies_every_pi_apt_cache_deb_into_the_drive_debs_with_the_packages_index_built_there(tmp_path):
    env = fake_build_env(tmp_path, tmp_path / "uv-calls")
    fake_command(tmp_path / "bin", "apt-ftparchive", """
[ "$1" = packages ] && [ "$2" = . ] && [ $# -eq 2 ] || exit 2
for f in *.deb; do printf 'Filename: %s/%s\\n' "$PWD" "$f"; done""")
    archives = Path(env["APTPI"]) / "var" / "cache" / "apt" / "archives"
    (archives / "mpv_0.39.0-3_arm64.deb").write_bytes(b"!<arch>\nmpv")
    drive = tmp_path / "drive"
    drive.mkdir()

    subprocess.run(["sh", str(BUILD_DRIVE), str(drive)], env=env)

    debs = drive / "mediatagger" / "debs"
    pi_debs = sorted(archives.glob("*.deb"))
    assert {p.name: p.read_bytes() for p in debs.iterdir()} == {
        **{p.name: p.read_bytes() for p in pi_debs},
        "Packages": "".join(f"Filename: {debs}/{p.name}\n" for p in pi_debs).encode(),
    }


def test_build_drive_takes_the_debs_from_the_home_aptpi_cache_when_aptpi_is_unset(tmp_path):
    env = fake_build_env(tmp_path, tmp_path / "uv-calls")
    del env["APTPI"]
    archives = Path(env["HOME"]) / "aptpi" / "var" / "cache" / "apt" / "archives"
    archives.mkdir(parents=True)
    (archives / "mpv_0.39.0-3_arm64.deb").write_bytes(b"!<arch>\nmpv")
    drive = tmp_path / "drive"
    drive.mkdir()

    subprocess.run(["sh", str(BUILD_DRIVE), str(drive)], env=env)

    debs = drive / "mediatagger" / "debs"
    assert {p.name: p.read_bytes() for p in debs.glob("*.deb")} == {"mpv_0.39.0-3_arm64.deb": b"!<arch>\nmpv"}


def test_build_drive_removes_a_deb_left_in_the_drive_debs_by_an_earlier_build(tmp_path):
    env = fake_build_env(tmp_path, tmp_path / "uv-calls")
    debs = tmp_path / "drive" / "mediatagger" / "debs"
    debs.mkdir(parents=True)
    stale = debs / "libmpv1_0.35.1-4_arm64.deb"
    stale.write_bytes(b"!<arch>\nold")

    subprocess.run(["sh", str(BUILD_DRIVE), str(tmp_path / "drive")], env=env)

    assert not stale.exists()


def test_build_drive_fails_naming_the_empty_apt_cache_and_leaves_no_drive_debs_when_aptpi_holds_no_deb(tmp_path):
    env = fake_build_env(tmp_path, tmp_path / "uv-calls")
    archives = Path(env["APTPI"]) / "var" / "cache" / "apt" / "archives"
    for deb in archives.glob("*.deb"):
        deb.unlink()
    drive = tmp_path / "drive"
    drive.mkdir()

    result = subprocess.run(["sh", str(BUILD_DRIVE), str(drive)], env=env, capture_output=True, text=True)

    assert {
        "failed": result.returncode != 0,
        "names_archives": str(archives) in result.stderr,
        "raw_cp_error": "cp:" in result.stderr,
        "debs_left": (drive / "mediatagger" / "debs").exists(),
    } == {"failed": True, "names_archives": True, "raw_cp_error": False, "debs_left": False}


def test_build_drive_lays_out_the_same_app_and_scripts_as_update_drive(tmp_path):
    env = fake_build_env(tmp_path, tmp_path / "uv-calls")
    built, updated = tmp_path / "built", tmp_path / "updated"
    built.mkdir()
    updated.mkdir()

    subprocess.run(["sh", str(BUILD_DRIVE), str(built)], env=env)
    subprocess.run(["sh", str(BUILD_DRIVE.parent / "update-drive.sh"), str(updated)], env=env, check=True)

    def app_and_scripts(drive):
        mediatagger = drive / "mediatagger"
        # Bytecode records the absolute path it was compiled at, so it is compared by name only.
        return {
            str(p.relative_to(mediatagger)): None if p.suffix == ".pyc" else p.read_bytes()
            for p in mediatagger.rglob("*")
            if p.is_file() and p.relative_to(mediatagger).parts[0] not in {"lib-linux-aarch64-cp313", "debs"}
        }
    assert app_and_scripts(built) == app_and_scripts(updated)


def test_build_drive_leaves_an_empty_metadata_never_index_at_the_drive_root(tmp_path):
    env = fake_build_env(tmp_path, tmp_path / "uv-calls")
    drive = tmp_path / "drive"
    drive.mkdir()

    subprocess.run(["sh", str(BUILD_DRIVE), str(drive)], env=env)

    marker = drive / ".metadata_never_index"
    assert marker.is_file() and marker.read_bytes() == b""


def test_build_drive_leaves_the_drive_tags_byte_identical_and_nothing_outside_its_mediatagger_folder_changed(tmp_path):
    env = fake_build_env(tmp_path, tmp_path / "uv-calls")
    drive = tmp_path / "drive"
    files = {
        drive / ".mediatagger" / "tags.db": b"SQLite format 3\x00tags",
        drive / ".mediatagger" / "tags.db-wal": b"\x37\x7f\x06\x82wal",
        drive / ".mediatagger" / "._tags.db": b"\x00\x05\x16\x07",
        drive / ".mediatagger" / "thumbs" / "clip.mov.jpg": b"\xff\xd8\xff\xe0thumb",
        drive / "photo.jpg": b"\xff\xd8\xff\xe0photo",
        drive / "._photo.jpg": b"\x00\x05\x16\x07",
        drive / "videos" / "nested" / "clip.mov": b"\x00\x00\x00\x14ftypqt",
    }
    for path, body in files.items():
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(body)
    (drive / "empty-folder").mkdir()

    def outside_mediatagger():
        return {
            str(p.relative_to(drive)): p.read_bytes() if p.is_file() else None
            for p in drive.rglob("*")
            if p.relative_to(drive).parts[0] not in {"mediatagger", ".metadata_never_index"}
        }
    before = outside_mediatagger()

    subprocess.run(["sh", str(BUILD_DRIVE), str(drive)], env=env)

    assert outside_mediatagger() == before


def test_build_drive_from_another_working_directory_installs_the_packages_uv_exports_from_this_repos_project(tmp_path):
    record = tmp_path / "uv-calls"
    env = fake_build_env(tmp_path, record)
    repo = BUILD_DRIVE.parent.parent
    bin_dir = tmp_path / "bin"
    (bin_dir / "uv").rename(bin_dir / "uv-recording")
    fake_command(bin_dir, "uv", f"""
case " $* " in *" export "*) ;; *) exec "{bin_dir / 'uv-recording'}" "$@";; esac
project=$PWD; prev=
for a; do
  case "$prev" in --project|--directory) project=$a;; esac
  case "$a" in --project=*|--directory=*) project=${{a#*=}};; esac
  prev=$a
done
[ "$(cd "$project" && pwd -P)" = "$(cd "{repo}" && pwd -P)" ] || exit 2
cat "{tmp_path / 'exported.txt'}\"""")
    drive = tmp_path / "drive"
    drive.mkdir()

    subprocess.run(["sh", str(BUILD_DRIVE), str(drive)], env=env, cwd=tmp_path / "home")

    exported = [
        positional_specs(call["args"]) | requirement_specs(call["requirements"])
        for call in uv_pip_install_calls(record)
    ]
    assert exported == [requirement_specs(EXPORTED)]


def test_build_drive_without_a_drive_argument_fails_with_its_usage_message_and_installs_or_writes_nothing(tmp_path):
    record = tmp_path / "uv-calls"
    env = fake_build_env(tmp_path, record)
    cwd = tmp_path / "home"

    result = subprocess.run(["sh", str(BUILD_DRIVE)], env=env, cwd=cwd, capture_output=True, text=True)

    usage = [line for line in result.stderr.splitlines() if "usage" in line.lower()]
    assert {
        "failed": result.returncode != 0,
        "usage_names_build_drive": any("build-drive.sh" in line for line in usage),
        "uv_calls": sorted(p.name for p in record.iterdir()),
        "written_in_cwd": sorted(p.name for p in cwd.iterdir()),
    } == {"failed": True, "usage_names_build_drive": True, "uv_calls": [], "written_in_cwd": []}


def test_build_drive_fails_and_lays_out_no_debs_app_or_never_index_marker_when_uv_pip_install_fails(tmp_path):
    env = fake_build_env(tmp_path, tmp_path / "uv-calls")
    fake_command(tmp_path / "bin", "uv", f"""
if [ "$1" = export ]; then cat "{tmp_path / 'exported.txt'}"; exit 0; fi
echo "error: no matching distribution" >&2
exit 1""")
    drive = tmp_path / "drive"
    drive.mkdir()

    result = subprocess.run(["sh", str(BUILD_DRIVE), str(drive)], env=env, capture_output=True, text=True)

    assert {
        "failed": result.returncode != 0,
        "debs": (drive / "mediatagger" / "debs").exists(),
        "app": (drive / "mediatagger" / "app").exists(),
        "metadata_never_index": (drive / ".metadata_never_index").exists(),
    } == {"failed": True, "debs": False, "app": False, "metadata_never_index": False}
